 imp:"전 세계 위험자산의 기준점입니다. 미국 주식이 세계 시가총액의 절반을 넘고, 한국을 포함한 대부분 시장이 S&P 500에 후행합니다. 그리고 이 지수는 실물 경제보다 '할인율(금리)'과 '기업 이익'의 함수라, 경기가 나빠도 금리가 내리면 오릅니다. 경기 지표와 주가가 자주 엇갈리는 이유입니다.",
 sched:{cyc:"실시간",when:"미국 정규장",time:"09:30~16:00 ET",next:"연속 (CPI·고용·FOMC 때 급변)"},
 why:["금리 동결이 길어지는 국면에서도 지수가 버티고 있습니다. AI 관련 대형주가 지수를 떠받치는 구조입니다.","상위 10종목 비중이 약 35%로 사상 최고 수준입니다. 지수는 오르는데 대부분 종목은 안 오르는 '쏠림 장세'가 이어지고 있습니다.","6월 FOMC에서 점도표가 인상 우세로 뒤집혔는데도 조정이 제한적이었습니다. 시장이 이익 성장으로 금리 부담을 상쇄할 수 있다고 보는 것입니다.","다만 실질금리가 오르면 밸류에이션 부담이 커집니다. PCE 전망 상향으로 실질금리가 0에 근접한 지금이 그 시험대입니다."],
 watch:"지수 자체보다 '동일가중 S&P 500(RSP)' 대비 성과를 보세요. 격차가 벌어질수록 소수 종목에 의존하는 취약한 상승입니다.",
