 series:S([["2월",4.15],["3월",4.25],["4월",4.45],["5월",4.55],["6월",4.35],["7월",4.4]]),
 extra:[["기준금리 상단","3.75%"],["장단기 스프레드","약 +0.65%p"],["2020년 저점","0.52%"],["2023년 고점","5.02%"]],
 what:"미국 재무부가 발행한 10년 만기 국채의 유통 수익률입니다. 전 세계에서 가장 안전한 자산으로 여겨져 모든 위험자산 가격의 기준선 역할을 합니다. 주택담보대출·회사채·신흥국 금리가 전부 여기에 얹혀 있습니다.",
 imp:"세계 금융의 중력입니다. 이 금리가 오르면 미래 현금흐름의 현재가치가 깎여 주식·부동산·금이 모두 눌립니다. 그리고 이 금리는 연준이 직접 정하는 게 아니라 시장이 '향후 10년 평균 정책금리 + 기대인플레 + 기간프리미엄'으로 만듭니다. 즉 연준에 대한 시장의 평가서입니다.",
 sched:{cyc:"실시간",when:"미국 채권시장",time:"08:00~17:00 ET",next:"연속 (CPI·고용·국채입찰 때 급변)"},
 why:["10년 금리가 기준금리 상단(3.75%)을 0.65%p 웃도는 수준에서 움직이고 있습니다. 정상적인 우상향 곡선입니다.","6월 FOMC의 매파 전환이 반영됐습니다. 점도표가 인상 우세로 뒤집히면서 시장이 향후 정책금리 경로를 위로 조정했습니다.","동시에 이란 사태발 기대인플레이션 상승도 금리를 밀어올렸습니다. 명목금리 = 실질금리 + 기대인플레이므로, 유가가 오르면 장기금리가 따라 오릅니다.","7월 들어 유가가 되밀리며 금리도 소폭 안정됐습니다. 지금 미국 장기금리는 사실상 유가의 함수입니다."],
 watch:"10년-2년 스프레드를 함께 보세요. 역전(마이너스)은 침체 신호로 유명하지만, 역전이 해소되는 시점이 실제로는 더 위험합니다. 과거 침체는 대부분 역전 해소 직후에 왔습니다.",
 url:"https://home.treasury.gov/resource-center/data-chart-center/interest-rates/",
 yr:{u:"%",lab:"연말 10년 금리",v:[2.45,2.41,2.69,1.92,0.93,1.51,3.88,3.88,4.57,4.2,4.4],n:["2.45%. 트럼프 당선 후 재정 확대 기대로 급등했습니다.","2.41%. 연준 3회 인상에도 장기금리는 안 올랐습니다. '그린스펀의 수수께끼' 재현입니다.","2.69%. 11월 3.24%까지 올랐다 연말 급락했습니다.","1.92%. 8월 장단기 금리가 역전되며 침체 우려가 커졌습니다.","0.93%. 3월 0.52%로 사상 최저. 제로금리와 QE의 결과입니다.","1.51%. 인플레 우려에도 연준이 '일시적'이라 해 낮게 유지됐습니다.","3.88%. 425bp 긴축으로 1년 만에 237bp 급등했습니다.","3.88%. 10월 5.02%까지 갔다 연말 급락했습니다.","4.57%. 연준이 내리는데 장기금리는 올랐습니다. 재정적자 우려가 원인입니다.","약 4.20%. 인하 사이클로 소폭 하락했습니다.","약 4.40%. 인상 편향 전환과 유가 상승으로 재상승 중입니다."],arc:"2020년 0.93%에서 2024년 4.57%까지. 40년간 이어진 금리 하락 추세가 끝났다는 것이 지난 11년의 가장 큰 사건입니다. 특히 2024년이 상징적입니다. 연준이 100bp를 내렸는데 10년 금리는 오히려 올랐습니다. 시장이 연준보다 재정적자와 인플레를 더 무겁게 본 것입니다. 중앙은행이 단기금리는 정해도 장기금리는 못 정한다는 사실이 확인된 해입니다."},
    url: "https://home.treasury.gov/resource-center/data-chart-center/interest-rates/",
