  "fomc|nfp":[-0.55,"금리 인상 → 자금조달 비용 상승 → 채용 축소. 전달에 6~12개월이 걸려 지금의 NFP 둔화에는 과거 긴축의 후행 효과가 섞여 있습니다."],
  "nfp|unrate":[-0.70,"고용이 늘면 실업률이 내립니다. 단, 6월처럼 참가율이 급락하면 둘이 함께 개선되는 착시가 생깁니다."],
  "nfp|claims":[-0.60,"해고가 늘면 청구가 늘고 순고용은 줄어듭니다. 지금은 이 관계가 깨졌습니다. 청구 18.7만(최저) + NFP 5.7만(부진) = 해고도 채용도 없는 동결 시장."],
