  "nfp|retail":[0.65,"일자리가 늘면 소득이 늘고 소비가 늡니다. GDP의 약 68%가 소비이므로 이 고리가 경기 순환의 엔진입니다."],
  "unrate|umich":[-0.68,"실업률이 오르면 심리가 나빠집니다. 다만 2026년엔 실업률(4.2%)이 안정적인데도 심리가 역대 최저였습니다. 원인이 고용이 아니라 물가였기 때문입니다."],
  "cpi|umich":[-0.80,"2026년의 지배적 관계입니다. 5월 심리 역대 최저(44.8)와 유가 급등이 정확히 겹칩니다. 7월 반등(54.4)도 유가 하락 때문입니다. 심리는 실업률보다 휘발유 가격에 반응했습니다."],
  "umich|retail":[0.40,"심리는 소비를 예고하지만 상관은 생각보다 약합니다. 사람들은 기분이 나빠도 필수품은 삽니다. '말한 것'과 '산 것'은 다릅니다."],
