  "housing|cpi":[0.55,"집값·임대료는 12~18개월 시차로 CPI 주거비(OER)에 반영됩니다. CPI의 약 1/3이라 시차가 길어도 영향은 매우 큽니다."],
  "housing|nfp":[0.50,"건설은 고용집약적입니다. 착공이 꺾이면 건설 일자리가 줄고, 이는 침체의 전통적 선행 신호였습니다."],
  "retail|cpi":[0.50,"소매판매는 명목 금액이라 물가가 오르면 자동으로 올라갑니다. '가짜 상관'이므로 반드시 실질로 환산하세요."],
  "umich|pce":[-0.55,"기대인플레가 오르면 심리가 나빠지고, 기대가 실제 물가에 영향을 주는 자기실현 경로도 있습니다. 연준이 5년 기대(3.3%)를 주시하는 이유입니다."],
