  "gold|fomc":[-0.72,"가장 중요한 금 관계입니다. 금은 이자를 안 주므로, 금리가 오르면 채권 대비 기회비용이 커져 불리해집니다. 반대로 인하 기대가 살아나면 금이 오릅니다. 금 가격은 사실상 '시장이 예상하는 실질금리'의 거울입니다."],
