  "gold|pce":[0.55,"PCE는 연준이 실제로 보는 숫자라 금리 경로를 통한 간접 효과가 CPI보다 강합니다. PCE 서프라이즈 당일 금 변동성이 가장 큽니다."],
  "gold|umich":[0.45,"미시간 5년 기대인플레이션과 금은 같이 움직입니다. 기대인플레가 오르면 실질금리(명목−기대)가 내려가고 금이 유리해집니다. 소비자심리 본지수가 아니라 기대인플레 항목을 보세요."],
