 imp:"수출 대기업의 성과가 국민 소득으로 흘러가는지를 확인하는 관문입니다. 2026년처럼 수출이 70% 늘어도 고용이 6만 명 증가에 그치면, 총량 성장과 체감 경기의 괴리가 커지고 내수는 살아나지 않습니다.",
 sched:["매월","대략 10~15일","08:00 KST","8월 12일경 (7월분)"],
 why:["6월 취업자는 전년 대비 6.3만 명 증가에 그쳤고 고용률은 63.4%로 0.2%p 하락했습니다.",
 "수출이 70% 폭증하는데 고용은 6.3만 명 증가에 머물렀다는 것이 핵심입니다. 반도체·조선은 자본집약적이라 매출이 늘어도 고용이 비례하지 않습니다.",
 "업종별로 서비스업은 증가폭을 확대했지만 건설업은 감소폭이 확대됐습니다. 부동산 PF 부실과 착공 위축의 후유증입니다.",
 "고용률 하락은 취업자 증가가 생산가능인구 증가를 못 따라갔다는 뜻입니다. 고령화가 진행되는 한국에서 이 격차는 구조적으로 커집니다."],
 watch:"'수출 호황 + 고용 부진'은 한국의 전형적 패턴입니다. 건설업 고용이 반등하는지가 내수 회복의 신호입니다.",
 url:"https://kostat.go.kr/board.es?mid=a10301010000&bid=210",
