/* 국가 데이터 정규화: series 배열 → 객체, sched 배열 → 객체 */
const normalize = (list) => list.map((d) => ({
  ...d,
  series: d.series.map(([m, v, ver]) => ({ m, v, ver: !!ver })),
  sched: { cyc: d.sched[0], when: d.sched[1], time: d.sched[2], next: d.sched[3] },
}));
Object.keys(CDATA).forEach((k) => { CDATA[k].ind = normalize(CDATA[k].ind); });

